#!/usr/bin/env bash
set -euo pipefail

PYTHON_BIN="${PYTHON_BIN:-python}"
LOG_ROOT="${LOG_ROOT:-logs_tuning/graphflashback_boi_nola}"
mkdir -p "$LOG_ROOT"

run_exp() {
  name="$1"
  shift
  log_file="$LOG_ROOT/${name}.log"
  echo "[GraphFlashback tune] start ${name} -> ${log_file}"
  "$PYTHON_BIN" "$@" --save "$name" > "$log_file" 2>&1 &
  pid=$!
  wait "$pid"
  echo "[GraphFlashback tune] done  ${name}"
}

COMMON="train_graphflashback_fair.py --gpu 0 --seed 42 --ns_q 1000 --ns_seed 42 --train_predict_ratio 0.0 --progress_every 200 --grad_norm 5.0 --time_period_seconds 86400"
BOI="$COMMON --dataset Yelp-BOI --batch_size 512 --eval_batch_size 1024 --evaluate_every 5 --patience 40"
NOLA="$COMMON --dataset Yelp-NOLA --batch_size 512 --eval_batch_size 1024 --evaluate_every 5 --patience 30"

run_exp boi_gfb_h32_l20_gru_lt01_ls100_fw008_geo25 $BOI --n_epochs 90 --hidden_dim 32 --sequence_length 20 --rnn gru --lr 0.001 --weight_decay 0.0 --lr_scheduler step --lr_step_size 30 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --spatial_threshold_km 2.5 --spatial_merge_weight 0.25 --friend_interact_weight 0.08 --friend_interact_topk 3 --rel_score_weight 0.8 --time_score_weight 0.1 --rel_bias_weight 0.8 --num_time_bins 128
run_exp boi_gfb_h48_l20_gru_lt01_ls100_fw008_geo25 $BOI --n_epochs 90 --hidden_dim 48 --sequence_length 20 --rnn gru --lr 0.001 --weight_decay 0.0 --lr_scheduler step --lr_step_size 30 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --spatial_threshold_km 2.5 --spatial_merge_weight 0.25 --friend_interact_weight 0.08 --friend_interact_topk 3 --rel_score_weight 0.8 --time_score_weight 0.1 --rel_bias_weight 0.8 --num_time_bins 128
run_exp boi_gfb_h64_l20_gru_lt005_ls50_fw005_geo15 $BOI --n_epochs 80 --hidden_dim 64 --sequence_length 20 --rnn gru --lr 0.0007 --weight_decay 0.0 --lr_scheduler step --lr_step_size 25 --lr_gamma 0.3 --lambda_t 0.05 --lambda_s 50 --lambda_loc 1.0 --spatial_threshold_km 1.5 --spatial_merge_weight 0.15 --friend_interact_weight 0.05 --friend_interact_topk 2 --rel_score_weight 1.0 --time_score_weight 0.1 --rel_bias_weight 1.0 --num_time_bins 128
run_exp boi_gfb_h48_l30_gru_lt01_ls100_fw010_geo25 $BOI --n_epochs 80 --hidden_dim 48 --sequence_length 30 --rnn gru --lr 0.0008 --weight_decay 0.0 --lr_scheduler step --lr_step_size 25 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --spatial_threshold_km 2.5 --spatial_merge_weight 0.25 --friend_interact_weight 0.10 --friend_interact_topk 3 --rel_score_weight 0.8 --time_score_weight 0.15 --rel_bias_weight 0.8 --num_time_bins 256
run_exp boi_gfb_h64_l30_gru_lt02_ls200_fw010_geo50 $BOI --n_epochs 70 --hidden_dim 64 --sequence_length 30 --rnn gru --lr 0.0005 --weight_decay 0.0 --lr_scheduler cosine --lambda_t 0.2 --lambda_s 200 --lambda_loc 1.0 --spatial_threshold_km 5.0 --spatial_merge_weight 0.30 --friend_interact_weight 0.10 --friend_interact_topk 4 --rel_score_weight 1.0 --time_score_weight 0.15 --rel_bias_weight 1.0 --num_time_bins 256
run_exp boi_gfb_h48_l40_gru_lt01_ls100_fw005_geo25 $BOI --n_epochs 60 --hidden_dim 48 --sequence_length 40 --rnn gru --lr 0.0007 --weight_decay 0.0 --lr_scheduler step --lr_step_size 20 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --spatial_threshold_km 2.5 --spatial_merge_weight 0.20 --friend_interact_weight 0.05 --friend_interact_topk 3 --rel_score_weight 0.8 --time_score_weight 0.15 --rel_bias_weight 0.8 --num_time_bins 256
run_exp boi_gfb_h48_l20_lstm_lt01_ls100_fw008_geo25 $BOI --n_epochs 70 --hidden_dim 48 --sequence_length 20 --rnn lstm --lr 0.0007 --weight_decay 0.0 --lr_scheduler step --lr_step_size 25 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --spatial_threshold_km 2.5 --spatial_merge_weight 0.25 --friend_interact_weight 0.08 --friend_interact_topk 3 --rel_score_weight 0.8 --time_score_weight 0.1 --rel_bias_weight 0.8 --num_time_bins 128
run_exp boi_gfb_h48_l20_gru_directed_nomgeo_fw008 $BOI --n_epochs 80 --hidden_dim 48 --sequence_length 20 --rnn gru --lr 0.001 --weight_decay 0.0 --lr_scheduler step --lr_step_size 25 --lr_gamma 0.3 --lambda_t 0.1 --lambda_s 100 --lambda_loc 1.0 --no_merge_spatial_into_transition --directed_transition --friend_interact_weight 0.08 --friend_interact_topk 3 --rel_score_weight 1.0 --time_score_weight 0.1 --rel_bias_weight 1.0 --num_time_bins 128

