run_exp nola_gfb_h64_l20_gru_lt005_ls50_fw003_geo15_bs384 $COMMON --dataset Yelp-NOLA --batch_size 384 --eval_batch_size 768 --evaluate_every 5 --patience 30 --n_epochs 60 --hidden_dim 64 --sequence_length 20 --rnn gru --lr 0.0005 --weight_decay 0.0 --lr_scheduler step --lr_step_size 20 --lr_gamma 0.3 --lambda_t 0.05 --lambda_s 50 --lambda_loc 1.0 --spatial_threshold_km 1.5 --spatial_merge_weight 0.15 --friend_interact_weight 0.03 --friend_interact_topk 2 --rel_score_weight 1.0 --time_score_weight 0.1 --rel_bias_weight 1.0 --num_time_bins 128
